reply:
```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology of securities, financial instruments and derivatives modeled from a descriptive corpus (Wikipedia-style articles, IAS 32/IFRS 9, ECB glossary, OpenStax, FINRA, CFI, BIS)." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "has issuer" ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Issuer ;
  rdfs:comment "The company or other entity issuing the security is called the issuer." .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:label "has holder" ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Investor .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ;
  rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:label "has underlying" ;
  rdfs:domain fis:Derivative ;
  rdfs:range owl:Thing ;
  rdfs:comment "A derivative's value depends on the performance of the underlier: a commodity, financial instrument, price index, currency, interest rate, or event." .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain owl:Thing ;
  rdfs:range fis:Derivative .

fis:hasCounterparty a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range owl:Thing .

fis:hasConversionRight a owl:ObjectProperty ;
  rdfs:label "has conversion right" ;
  rdfs:domain fis:HybridSecurity ;
  rdfs:range fis:EquitySecurity ;
  rdfs:comment "Relates a hybrid security to the equity security into which it may be converted at the holder's election." .

fis:hasEmbeddedOption a owl:ObjectProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Option ;
  rdfs:comment "Occasionally a bond or preferred share may contain an embedded option granting call or put rights." .

fis:hasReferenceEntity a owl:ObjectProperty ;
  rdfs:domain fis:CreditDefaultSwap ;
  rdfs:range owl:Thing ;
  rdfs:comment "The debt issuer or obligation whose creditworthiness underlies a credit default swap." .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:AssetBackedSecurity ;
  rdfs:range owl:Thing ;
  rdfs:comment "Relates an asset-backed security to the pool of assets (e.g. mortgages, debt obligations) backing its cash flows." .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "has maturity date" ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range xsd:date ;
  rdfs:comment "The date on which the issuer is obligated to repay the nominal/principal amount." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "has face value" ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range xsd:decimal ;
  rdfs:comment "Nominal, principal, par, or face amount: the amount on which interest is paid and which is repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "has coupon rate" ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The interest rate that the issuer pays to the holder." .

fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:Security ;
  rdfs:range xsd:string .

fis:hasDividend a owl:DatatypeProperty ;
  rdfs:domain fis:EquitySecurity ;
  rdfs:range xsd:decimal ;
  rdfs:comment "A discretionary portion of a company's profit paid to shareholders; unlike a coupon, not a fixed contractual obligation." .

fis:hasNotionalAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Swap ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The nominal amount used to calculate swap payments; generally not exchanged between counterparties." .

fis:hasConversionPrice a owl:DatatypeProperty ;
  rdfs:domain fis:ConvertibleBond ;
  rdfs:range xsd:decimal .

fis:hasConversionRatio a owl:DatatypeProperty ;
  rdfs:domain fis:ConvertibleBond ;
  rdfs:range xsd:decimal .

fis:hasNetAssetValue a owl:DatatypeProperty ;
  rdfs:domain fis:Fund ;
  rdfs:range xsd:decimal .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "has strike price" ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:date .

fis:hasPremium a owl:DatatypeProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal .

fis:hasOptionType a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:string ;
  rdfs:comment "Values: 'call' or 'put'." .

fis:hasExerciseStyle a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:string ;
  rdfs:comment "Values include 'American', 'European', 'Bermudan', 'Asian', 'Barrier', 'Binary', 'Exotic'." .

fis:isExchangeTraded a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:boolean ;
  rdfs:comment "True if the derivative is traded on a regulated exchange; false if privately negotiated over the counter." .

fis:hasRegistrationForm a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range xsd:string ;
  rdfs:comment "Values: 'bearer', 'registered', or 'book-entry'. Certificates may be bearer (rights by mere possession) or registered (rights only if on issuer's register); non-certificated securities are book-entry/dematerialized." .

fis:hasDividendAccumulation a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:PreferredStock ;
  rdfs:range xsd:boolean ;
  rdfs:comment "True for cumulative preferred stock, where unpaid dividends accumulate; false for noncumulative/straight preferred stock." .

#################################################################
# TOP-LEVEL TAXONOMY
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "Financial Instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "An instrument whose value is determined directly by markets; includes securities and instruments such as loans and deposits." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom owl:Thing ]
    )
  ] ;
  rdfs:comment "Instruments that derive their value from the value and characteristics of one or more underlying entities. NOTE (conflict): US securities-law passages classify derivatives as a category of 'security' alongside debt and equity, while other passages treat derivatives as a separate category of financial instrument distinct from securities (cash instruments); this ontology follows the latter, more structurally explicit, description and records the conflict here." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CashInstrument fis:Derivative ) .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:DebtObligation a owl:Class ; rdfs:comment "A generic pool of debt assets (e.g. loans, bonds) used as collateral for a structured security." .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Security" ;
  rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns and can be traded in financial markets." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Security fis:Loan fis:Deposit ) .

#################################################################
# SECURITY: DEBT / EQUITY / HYBRID
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Debt Security" ;
  rdfs:comment "Holder entitled to payment of principal and interest; generally issued for a fixed term and redeemable by the issuer at the end of the term." .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Equity Security" ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership." .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "Combines some of the characteristics of both debt and equity securities." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:DebtSecurity fis:EquitySecurity fis:HybridSecurity ) .

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Short term debt instrument with original maturity of one year or less; may have characteristics of deposit accounts." .

#################################################################
# REGISTRATION FORM / DIVIDED-UNDIVIDED / FUNGIBILITY / OFFERING
#################################################################

fis:BearerSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "bearer" ] ) ] ;
  rdfs:comment "Completely negotiable; entitles the holder to rights under the security merely by holding it." .

fis:RegisteredSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "registered" ] ) ] ;
  rdfs:comment "Entitles the holder to rights only if the holder appears on a security register maintained by the issuer or an intermediary." .

fis:BookEntrySecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "book-entry" ] ) ] ;
  rdfs:comment "Non-certificated: electronic (dematerialized) or book-entry only form." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Each divided security constitutes a separate asset, legally distinct from each other security in the same issue." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue makes up one single asset, with each security being a fractional part of the undivided whole." .
[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "All holdings of the security are treated identically and are interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security .
[] a owl:AllDisjointClasses ; owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) .

fis:PubliclyOfferedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:PrivatelyPlacedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Offered privately to a limited number of qualified persons; not publicly tradable." .
[] a owl:AllDisjointClasses ; owl:members ( fis:PubliclyOfferedSecurity fis:PrivatelyPlacedSecurity ) .

#################################################################
# ISSUERS AND INVESTORS
#################################################################

fis:Issuer a owl:Class ; rdfs:comment "The entity which is obligated on a security or other financial instrument." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:MunicipalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:FinancialInstitution a owl:Class ; rdfs:subClassOf fis:Issuer .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Corporation fis:SovereignGovernment fis:MunicipalGovernment fis:SupranationalOrganization fis:FinancialInstitution ) .

fis:Investor a owl:Class ; rdfs:comment "A natural or legal person that holds securities." .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Members of the public investing personally, other than by way of business." .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Financial institutions acting on their own account, or on behalf of clients." .
[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) .

fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Investor
    [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Investor
    [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:Bond ] ) ] .

#################################################################
# BONDS
#################################################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Bond" ;
  rdfs:comment "Issuer (debtor) owes holder (creditor) a debt, obliged to provide cash flow consisting of repaying the principal at maturity, and usually interest (coupon)." .

fis:Debenture a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "An unsecured bond, backed only by the general creditworthiness of the issuer." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Bond fis:MoneyMarketInstrument ) .

# -- By issuer --
fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "Government Bond", "Sovereign Bond", "Treasury Bond" .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:MunicipalGovernment ] ) ] ;
  rdfs:label "Municipal Bond" .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public sector assets which remain on the issuer's balance sheet (unlike ABS)." .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Lower priority than senior bonds of the same issuer in case of liquidation." .

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:label "Junk Bond" .
[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) .

# -- By coupon structure --
fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:StepCouponBond a owl:Class ; rdfs:subClassOf fis:FixedRateBond ;
  rdfs:comment "Coupon increases during the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Variable coupon linked to a money-market reference rate." .
fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0"^^xsd:decimal ] ) ] ;
  rdfs:comment "Pays no regular interest; issued at a substantial discount to par value." .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "Inflation-Linked Bond" .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond fis:InflationIndexedBond fis:LotteryBond ) .

# -- Optionality --
fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] ;
  rdfs:comment "Issuer may repay the bond before the maturity date on call dates." .

fis:PutableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] ;
  rdfs:label "Retractable Bond" .

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasConversionRight ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Lets a bondholder exchange the bond for a number of shares of the issuer's common stock." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "Perpetuity" ;
  rdfs:comment "Has no maturity date; the principal is repaid only at the discretion of the issuer, if ever." .

fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

fis:ForeignCurrencyBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued in a currency other than the issuer's domestic currency, e.g. a samurai bond." .

# -- Registration form for bonds --
fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BearerSecurity .
fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:RegisteredSecurity .
fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BookEntrySecurity .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) .

#################################################################
# US TREASURY SECURITIES / UK GILTS
#################################################################

fis:USTreasurySecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:label "Treasury Security" .

fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:USTreasurySecurity, fis:MoneyMarketInstrument ;
  rdfs:comment "Zero-coupon bond maturing in one year or less, bought at a discount." .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:USTreasurySecurity ;
  rdfs:comment "Maturity of two, three, five or ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:USTreasurySecurity ;
  rdfs:comment "Longest maturity, from twenty to thirty years." .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:USTreasurySecurity, fis:InflationIndexedBond .
fis:TreasuryFloatingRateNote a owl:Class ; rdfs:subClassOf fis:USTreasurySecurity, fis:FloatingRateNote .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:TreasuryBill fis:TreasuryNote fis:TreasuryBond fis:TreasuryInflationProtectedSecurity fis:TreasuryFloatingRateNote ) .

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "UK government bond." .
fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:Gilt, fis:FixedRateBond .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:Gilt, fis:InflationIndexedBond .
[] a owl:AllDisjointClasses ; owl:members ( fis:ConventionalGilt fis:IndexLinkedGilt ) .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom owl:Thing ] ) ] ;
  rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from a pool of other assets. NOTE: the corpus uses 'asset-backed security' both as an umbrella term (covering MBS and CDO) and, in a narrower sense, for securities backed specifically by consumer loans/receivables other than real estate; this ontology models the umbrella sense as primary and records the narrower usage here as a conflict." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "MBS" .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:label "CDO" ;
  rdfs:comment "'Sliced' into tranches that catch cash flow of interest and principal in sequence based on seniority." .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Interest and principal payments from the borrower pass through to the holder." .
fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:PassThroughSecurity ;
  rdfs:label "RMBS" .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:PassThroughSecurity ;
  rdfs:label "CMBS" .
[] a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "CMO", "Pay-Through Bond" .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "SMBS" .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "IO" .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "PO" .
[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days." .
fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "CD", "Time Deposit" .
fis:JumboCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:CertificateOfDeposit ;
  rdfs:comment "Minimum deposit of $100,000; negotiable, in bearer form." .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .
fis:FederalFundsInstrument a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument, fis:MunicipalBond .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:BankersAcceptance fis:RepurchaseAgreement fis:FederalFundsInstrument ) .

#################################################################
# EQUITY SECURITIES / STOCK
#################################################################

fis:Stock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "Consists of all the shares by which ownership of a corporation is divided." .

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:Stock ;
  rdfs:label "Ordinary Share" ;
  rdfs:comment "Typically carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
  rdfs:label "Preference Share" ;
  rdfs:comment "Senior to common stock but subordinate to bonds; has priority in dividend payment and liquidation; a hybrid instrument." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:CumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue true ] ) ] .

fis:NonCumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue false ] ) ] ;
  rdfs:label "Straight Preferred Stock" .

[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NonCumulativePreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasConversionRight ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:CallablePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:FinancialInstitution ]
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:label "DR" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "ADR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "EDR" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "GDR" .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# HYBRID SECURITIES (OTHER)
#################################################################

fis:EquityWarrant a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Options issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .
[] a owl:AllDisjointClasses ; owl:members ( fis:LockProduct fis:OptionProduct ) .

fis:ExchangeTradedDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
  rdfs:label "ETD" .
fis:OverTheCounterDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
  rdfs:label "OTC Derivative" .
[] a owl:AllDisjointClasses ; owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) .

fis:Forward a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
    [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at an amount agreed today." .

fis:ForwardRateAgreement a owl:Class ; rdfs:subClassOf fis:Forward ; rdfs:label "FRA" .

fis:Future a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
    [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
  rdfs:comment "A standardized contract written by a clearing house that operates an exchange where the contract can be bought and sold." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Forward fis:Future fis:Swap ) .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:comment "Two counterparties exchange cash flows of one party's financial instrument for those of the other's." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ;
  rdfs:subClassOf fis:Swap ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
    [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom owl:Thing ] ) ] ;
  rdfs:label "CDS" .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap fis:CommoditySwap fis:EquitySwap ) .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:ExchangeTradedOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
  rdfs:label "Listed Option" .
fis:OverTheCounterOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
  rdfs:label "Dealer Option" .
[] a owl:AllDisjointClasses ; owl:members ( fis:ExchangeTradedOption fis:OverTheCounterOption ) .

fis:CallOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] ;
  rdfs:comment "The right, not the obligation, to buy." .
fis:PutOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] ;
  rdfs:comment "The right, not the obligation, to sell." .
[] a owl:AllDisjointClasses ; owl:members ( fis:CallOption fis:PutOption ) .

fis:AmericanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .
fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying's price must pass a certain barrier before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "All-or-nothing option paying the full amount if a condition is met at expiration." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption fis:AsianOption fis:BarrierOption fis:BinaryOption fis:ExoticOption ) .

#################################################################
# FUNDS
#################################################################

fis:Fund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "A collective investment undertaking that pools money from many investors to purchase securities." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "An SEC-registered open-end investment company pooling money to invest in a diversified portfolio." .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:label "ETF" ;
  rdfs:comment "Investors buy and sell shares on exchanges at market prices that may differ from net asset value." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "Pools money from investors with fewer regulatory protections and more flexible, riskier strategies." .
fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:Fund .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Income Fund" .
fis:EquityFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Stock Fund" .
fis:IndexFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "Passively managed fund tracking the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:Fund .
[] a owl:AllDisjointClasses ; owl:members ( fis:IndexFund fis:ActivelyManagedFund ) .

fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:Fund .
fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:Fund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:Fund .
[] a owl:AllDisjointClasses ; owl:members ( fis:ClosedEndFund fis:OpenEndFund fis:UnitInvestmentTrust ) .

fis:IndexExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund, fis:IndexFund .
fis:InverseExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
  rdfs:comment "Designed to move opposite to its benchmark." .
fis:LeveragedExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
  rdfs:comment "Seeks to amplify the benchmark's daily return." .

#################################################################
# ACCOUNTING CLASSIFICATION (IAS 32 / IFRS 9)
#################################################################

fis:FinancialAsset a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "IAS 32: cash; an equity instrument of another entity; a contractual right to receive cash or another financial asset; or a contractual right to exchange financial assets/liabilities under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset, or to exchange financial assets/liabilities under potentially unfavourable conditions." .

fis:EquityInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  owl:disjointWith fis:FinancialLiability ;
  rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. CONFLICT NOTE: classification as equity vs. financial liability depends on contractual substance, not label -- e.g. a mandatorily redeemable preference share is a FinancialLiability under IAS 32 even though the market commonly calls it 'preferred equity' (cf. fis:PreferredStock)." .

fis:CompoundFinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "IAS 32: an instrument such as a convertible bond that must be split into a liability component and an equity component." .

fis:AmortizedCostFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset .
fis:FairValueOCIFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ; rdfs:label "FVOCI Asset" .
fis:FairValueThroughProfitOrLossFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ; rdfs:label "FVTPL Asset" .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmortizedCostFinancialAsset fis:FairValueOCIFinancialAsset fis:FairValueThroughProfitOrLossFinancialAsset ) .

fis:EquityInvestment a owl:Class ;
  rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "IFRS 9: equity investments are always measured at fair value, either FVTPL by default or FVOCI by irrevocable election." .
